def transform(wb):
    src = wb["Sheet1"]
    if "Sheet2" not in wb.sheetnames:
        dst = wb.create_sheet("Sheet2")
    else:
        dst = wb["Sheet2"]
    for row in range(1, 19):
        for col in range(1, 4):
            dst.cell(row=row, column=col, value=None)
    for col in range(1, 4):
        dst.cell(row=2, column=col, value=src.cell(row=1, column=col).value)
    out_row = 3
    for row in range(2, 19):
        b = src.cell(row=row, column=2).value
        c = src.cell(row=row, column=3).value
        if b == "TELIVISION" or c == "CLASS III" or c == "CLASS IV":
            for col in range(1, 4):
                dst.cell(row=out_row, column=col, value=src.cell(row=row, column=col).value)
            out_row += 1
    return None
